def parse_count(text):
    if not text.isdigit():
        raise ValueError("invalid literal for int()")
    return int(text)

def load_record(row):
    return parse_count(row["count"])

try:
    load_record({"count": "3x"})
except ValueError as exc:
    print(type(exc).__name__, str(exc))

